            nonzero,
            verify_state.clone(),
            "divisor must be non-zero".to_string(),
        )?);
        reqs.push(self.require_obj_in_c(value.left.as_ref(), verify_state.clone())?);
        reqs.push(self.require_obj_in_c(value.right.as_ref(), verify_state)?);
