        let hi = AtomicFact::LessEqualFact(LessEqualFact {
            fact_id: self.global_ids.allocate_fact_id(),
            left: value.arg.as_ref().clone(),
            right: one,
            line_file: None,
        });
        reqs.push(self.verify_required_atomic_fact(
            lo,
            verify_state.clone(),
            "arcsin: argument must be >= -1".to_string(),
        )?);
        reqs.push(self.verify_required_atomic_fact(
            hi,
            verify_state,
            "arcsin: argument must be <= 1".to_string(),
